package com.vandorlabs.neoforge;

import com.mojang.blaze3d.vertex.*;
import com.vandorlabs.neoforge.segmented.*;
import com.vandorlabs.persistence.SegmentedWindowLayout;
import java.util.*;
import net.minecraft.client.*;
import net.minecraft.client.renderer.*;
import net.minecraft.client.renderer.texture.*;
import net.minecraft.client.resources.model.*;
import net.minecraft.core.Direction;
import net.minecraft.resources.ResourceLocation;
import net.neoforged.api.distmarker.Dist;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.client.event.*;

/** Real atlas: moving-column and closed terrain consumers must draw identical Tile phase. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class NativeSegmentedTileRenderChecks {
 private static NativeSegmentedRenderer.Bake moving;private static NativeSegmentedTerrainModel.Bake terrain;private static NativeSegmentedVisual[] columns;private static int texture,frames,generation;private static int[] negative;private static boolean capture,done;
 private static final class Gallery extends net.minecraft.client.gui.screens.Screen { Gallery(){super(net.minecraft.network.chat.Component.literal("Segmented Tile"));} @Override public void render(net.minecraft.client.gui.GuiGraphics gui,int x,int y,float partial){} }
 private static final int[] LIGHTS={0xf000f0,0xf000f0,0xf000f0};
 private static void need(boolean ok,String why){if(!ok)throw new AssertionError("Segmented Tile render: "+why);}
 private static void prepare(){var mc=Minecraft.getInstance();texture=-1;for(int i=0;i<ModernFinishCatalog.ENTRIES.size();i++)if(ModernFinishCatalog.ENTRIES.get(i).id().equals("company_door_pinnacle_light")){texture=i;break;}need(texture>=0,"actual tall company artwork");var materials=NativePanelPlaybackRenderer.currentBake();need(materials!=null,"active shared atlas generation");moving=new NativeSegmentedRenderer.Bake(materials,m->mc.getTextureAtlas(m.atlasLocation()).apply(m.texture()));var header=mc.getModelManager().getModel(ModelResourceLocation.standalone(NativeSegmentedTerrainModel.HEADER));terrain=new NativeSegmentedTerrainModel.Bake(Map.of(ModelResourceLocation.standalone(NativeSegmentedTerrainModel.HEADER),header),moving,mc.getResourceManager());columns=new NativeSegmentedVisual[4];for(int column=0;column<4;column++){boolean window=(column&1)==0;var cfg=new NativeSegmentedDoorSettings(0,false,1,0,window,2,false,NativeSegmentedDoorSettings.DEFAULT.glass,0);columns[column]=new NativeSegmentedVisual(4,3,column,Direction.NORTH,texture,cfg,List.of(cfg,cfg,cfg),List.of(SegmentedWindowLayout.SINGLE,SegmentedWindowLayout.SINGLE,SegmentedWindowLayout.SINGLE),true,false,false,!window);for(int row=0;row<3;row++)terrain.quads(snapshot(column,row,false));}var body=moving.artwork(texture).surface();need(Math.abs(body.aspect-.5)<1e-6,"actual image aspect .5");}
 private static NativeSegmentedTerrainSnapshot snapshot(int column,int row,boolean oldPhase){return new NativeSegmentedTerrainSnapshot(Direction.NORTH,texture,row==0,true,row==0,row==2,1,column,oldPhase?0:row);}
 @SubscribeEvent public static void draw(ScreenEvent.Render.Post event){if(done||!"true".equals(System.getenv("VANDOR_SEGMENTED_TILE_CHECK")) )return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen){mc.setScreen(new Gallery());return;}if(!(event.getScreen() instanceof Gallery))return;if(moving==null)prepare();var gui=event.getGuiGraphics();gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();var buffers=mc.renderBuffers().bufferSource();
  for(int scene=0;scene<2;scene++){var poses=gui.pose();poses.pushPose();try{poses.translate(10+scene*320,86,300);poses.scale(65,-65,65);for(int column=0;column<4;column++){poses.pushPose();try{poses.translate(column,0,0);boolean bodyTerrain=scene==1&&(column&1)!=0;if(!bodyTerrain)NativeSegmentedRenderer.renderAt(moving,columns[column],0,poses,buffers,LIGHTS,OverlayTexture.NO_OVERLAY);var consumer=buffers.getBuffer(NativePanelPlaybackRenderer.frameRenderType());if(bodyTerrain){for(int row=0;row<3;row++){poses.pushPose();try{poses.translate(0,-row,0);for(var quad:terrain.quads(snapshot(column,row,frames<5)))consumer.putBulkData(poses.last(),quad,1,1,1,1,0xf000f0,OverlayTexture.NO_OVERLAY,true);}finally{poses.popPose();}}}else{var header=new NativeSegmentedTerrainSnapshot(Direction.NORTH,texture,true,false,true,false,1,column,0);for(var quad:terrain.quads(header))consumer.putBulkData(poses.last(),quad,1,1,1,1,0xf000f0,OverlayTexture.NO_OVERLAY,true);}}finally{poses.popPose();}}}finally{poses.popPose();}buffers.endBatch();gui.flush();}
  gui.renderItem(new net.minecraft.world.item.ItemStack(NativeSegmentedRegistrations.ITEM.get()),603,20);gui.flush();capture=++frames>=10;
 }
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception{if(done||(!capture&&frames!=5))return;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){int scale=(int)mc.getWindow().getGuiScale(),x0=10*scale,y0=21*scale,w=260*scale,h=195*scale;if(frames==5){negative=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++)negative[y*w+x]=image.getPixelRGBA(x0+320*scale+x,y0+y);return;}done=true;int mismatch=0,changed=0,ink=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int left=image.getPixelRGBA(x0+x,y0+y),right=image.getPixelRGBA(x0+320*scale+x,y0+y);if(left!=right)mismatch++;if(right!=negative[y*w+x])changed++;if((left&0xffffff)!=0x302820)ink++;}var diagnostic=mc.gameDirectory.toPath().resolve("screenshots/segmented-tile-diagnostic-"+generation+".png");java.nio.file.Files.createDirectories(diagnostic.getParent());image.writeToFile(diagnostic);int maxDelta=0,large=0;for(int y=0;y<h;y++)for(int x=0;x<w;x++){int a=image.getPixelRGBA(x0+x,y0+y),b=image.getPixelRGBA(x0+320*scale+x,y0+y),delta=0;for(int shift=0;shift<24;shift+=8)delta=Math.max(delta,Math.abs(((a>>>shift)&255)-((b>>>shift)&255)));maxDelta=Math.max(maxDelta,delta);if(delta>1)large++;}System.out.println("[vandorlabs][segmented-tile] diagnostic mismatch="+mismatch+" maxChannelDelta="+maxDelta+" aboveOne="+large);need(ink>10000,"actual mixed artwork visible");need(changed>1000,"wrong row-phase negative control changes actual pixels "+changed);need(mismatch<100,"moving/window vs closed-terrain Tile pixels disagree "+mismatch);int icon=0;for(int y=0;y<16*scale;y++)for(int x=0;x<16*scale;x++)if((image.getPixelRGBA(603*scale+x,20*scale+y)&0xffffff)!=0x302820){icon++;need(x>0&&x<16*scale-1&&y>0&&y<16*scale-1,"item icon padded on every edge");}need(icon>20,"actual two-pixel item visible");need(terrain.retainedBytes()<=16*1024*1024&&moving.snapshotBytes()<=16*1024*1024,"bounded bake caches");var path=mc.gameDirectory.toPath().resolve("screenshots/segmented-tile-"+generation+".png");java.nio.file.Files.createDirectories(path.getParent());image.writeToFile(path);System.out.println("[vandorlabs][segmented-tile] generation="+generation+" movingTerrainPixelMismatches="+mismatch+" negativePhasePixels="+changed+" itemPixels="+icon);}
  if(generation++==0){moving=null;terrain=null;columns=null;negative=null;frames=0;capture=done=false;mc.reloadResourcePacks();return;}System.out.println("[vandorlabs][segmented-tile] title PASS actualTallAtlas/mixedSolidWindows/terrainPhase/negativeControl/itemPadding/resourceReload");mc.stop();
 }
}
